// p5.js and WebGL setup
let canvas;
let gl;
let shaderProgram;

function setup() {
  canvas = createCanvas(600, 600, WEBGL);
  gl = canvas.GL;
  shaderProgram = createShaderProgram(vertexShader, fragmentShader);
}

function draw() {
  background(255);
  lights();
  translate(0, 0, -200);
  rotateY(frameCount * 0.01);
  fill(255, 0, 0); // red
  drawHeartFractal(200);
}

function drawHeartFractal(size) {
  // Fractal equation (Mandelbrot set-like)
  let z = complex(0, 0);
  let c = complex(size, 0);

  for (let i = 0; i < 10; i++) {
    z = complex(z.real * z.real - z.imag * z.imag + c.real, 2 * z.real * z.imag + c.imag);
    if (z.mod() > 2) break;
  }

  // Draw the fractal
  beginShape(QUAD_STRIP);
  for (let j = 0; j < 360; j++) {
    let angle = j * TWO_PI / 360;
    let x = size * 0.5 * (cos(angle) + 1);
    let y = size * 0.5 * (sin(angle) + 1);
    vertex(x, y, 0);
    let zStart = complex(x, y);
    for (let k = 0; k < 5; k++) {
      zStart = complex(zStart.real * zStart.real - zStart.imag * zStart.imag + c.real, 2 * zStart.real * zStart.imag + c.imag);
      if (zStart.mod() > 2) break;
    }
    let zEnd = zStart;
    line(x, y, 0, x + (zEnd.real - zStart.real) * size * 0.1, y + (zEnd.imag - zStart.imag) * size * 0.1, 0);
  }
  endShape();
}

function complex(real, imag) {
  return { real: real, imag: imag };
}

function complex(A, B) {
  return { real: A.real + B.real, imag: A.imag + B.imag };
}

function mod(A) {
  return Math.sqrt(A.real * A.real + A.imag * A.imag);
}
```

