import React, { useState, useEffect } from 'react';

const Autocomplete = ({ suggestions, onSelect }) => {
  const [term, setTerm] = useState('');
  const [filteredSuggestions, setFilteredSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (term && term.length > 0) {
        const filteredSuggestions = suggestions.filter((suggestion) => {
          return suggestion.toLowerCase().includes(term.toLowerCase());
        });
        setFilteredSuggestions(filteredSuggestions);
        setShowSuggestions(true);
      } else {
        setFilteredSuggestions([]);
        setShowSuggestions(false);
      }
    }, 300);
    return () => {
      clearTimeout(timeoutId);
    };
  }, [term, suggestions]);

  const handleInputChange = (event) => {
    setTerm(event.target.value);
  };

  const handleSelection = (suggestion) => {
    onSelect(suggestion);
    setTerm('');
  };

  return (
    <div>
      <input
        type="text"
        value={term}
        onChange={handleInputChange}
        placeholder="Type to search..."
      />
      {showSuggestions && (
        <ul>
          {(filteredSuggestions.length > 0 ? (
            filteredSuggestions.map((suggestion, index) => (
              <li key={index} onClick={() => handleSelection(suggestion)}>
                {suggestion}
              </li>
            ))
          ) : (
            <li>No results found</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
```
Here's a breakdown of how the component works:

* We have three states: `term` to store the user's input, `filteredSuggestions` to store the filtered list of suggestions, and `showSuggestions` to control whether to display the suggestions or not.
* We use the `useEffect` hook to fetch the filtered suggestions when the user types something. We set a timeout to wait for 300ms before fetching the suggestions, to avoid fetching new suggestions on every key press.
* We have two event handlers: `handleInputChange` to update the `term` state when the user types something, and `handleSelection` to select a suggestion when the user clicks on it.
* We render the input field with a placeholder, and an unordered list of suggestions when `showSuggestions` is true.
* When the user types something, we filter the suggestions using the `filter` method and update the `filteredSuggestions` state.
* When the user selects a suggestion, we call the `onSelect` callback with the selected suggestion, and reset the `term` state to an empty string.

