Java_ClassTransformer_load(JNIEnv *env, jobject obj) {
    // Get the JavaVM instance
    JavaVM *jvm = env->GetJavaVM();

    // Create a new class transformer
    JVMTITransformer transformer = {
        .transform = class_transform,
        .peer = NULL
