    // Check if the method is the one we're interested in
    if (strcmp(methodName, "hello") == 0) {
        // Replace the method body with a new implementation
        env->SetMethodBody(method, new_method_body);
    }

    return 0;
}

// New method body
jint new_method_body(JNIEnv *env, jobject method, jobject param) {
    // Call the original method to ensure the same semantics
    jint result = env->CallObjectMethod(method, param);

    // Do something with the result
